CREATE TYPE "CertificateStatus" AS ENUM ('VALID', 'REVOKED');
CREATE TABLE "CertificateTemplate" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "imageData" TEXT NOT NULL, "fields" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CertificatePolicy" ("courseId" TEXT PRIMARY KEY REFERENCES "Course"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "requireExam" BOOLEAN NOT NULL DEFAULT FALSE, "minimumAttendance" DOUBLE PRECISION NOT NULL DEFAULT 0, "templateId" TEXT NOT NULL);
CREATE TABLE "Certificate" ("id" TEXT PRIMARY KEY, "code" TEXT NOT NULL UNIQUE, "courseId" TEXT NOT NULL REFERENCES "Course"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "studentId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "templateId" TEXT NOT NULL REFERENCES "CertificateTemplate"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "status" "CertificateStatus" NOT NULL DEFAULT 'VALID', "issuedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "pdf" BYTEA NOT NULL, UNIQUE("courseId", "studentId"));
CREATE INDEX "Certificate_studentId_idx" ON "Certificate"("studentId");
